// The original kernel performed, for each time step:
//   1) B <- stencil(A)
//   2) A <- stencil(B)
// over the interior region of the 3D grid.
//
// This version preserves the exact computation, but improves spatial
// locality in i and j by:
//   * blocking the interior domain into tiles of size tile_i x tile_j
//   * hoisting tile indices to the outer loops
// while keeping k as the innermost (contiguous) dimension.
//
// If (n - 2) is not divisible by the chosen tile sizes, we transparently
// fall back to the original (non-tiled) traversal, so the code remains
// correct for all problem sizes.
//
[[gnu::flatten, gnu::noinline]]
void kernel_heat_3d(int tsteps, int n, auto A, auto B) {
	using namespace noarr;

	// Weights of the stencil, kept as constants so the compiler can fold them.
	constexpr num_t weight = num_t(0.125);
	constexpr num_t two    = num_t(2.0);

	// Interior region: i, j, k in [1, n-2]
	auto interior =
		noarr::slice<'i'>(1, n - 2) ^
		noarr::slice<'j'>(1, n - 2) ^
		noarr::slice<'k'>(1, n - 2);

	// Time "dimension" using broadcast: repeats the same spatial domain tsteps times
	auto time_bcast = noarr::bcast<'t'>(tsteps);

	// Tile sizes (can be tuned at compile time, see tuning_params above)
	const int tile_i = tuning_params::tile_i;
	const int tile_j = tuning_params::tile_j;

	// We only apply regular blocking when the interior size is a multiple
	// of the chosen tile size. Otherwise, we fall back to the original
	// non-tiled traversal to avoid out-of-bounds complications.
	const int inner_len = n - 2;
	const bool can_tile_i = (inner_len % tile_i) == 0;
	const bool can_tile_j = (inner_len % tile_j) == 0;
	const bool use_tiling = can_tile_i && can_tile_j;

	// Common per-time-step computation. The argument is a traverser whose
	// iteration space covers exactly the spatial domain of one time step
	// (blocked or not).
	auto do_time_step = [=](auto inner_trav) {
		// First sweep: update B from A
		inner_trav.for_each([=](auto state) {
			using noarr::idx;

			// state contains at least 'i', 'j', 'k' (and possibly tiling
			// indices such as 'I'/'J' which A/B ignore).
			const num_t center = A[state];

			const num_t lap_i =
				A[state + idx<'i'>(1)] - two * center +
				A[state - idx<'i'>(1)];
			const num_t lap_j =
				A[state + idx<'j'>(1)] - two * center +
				A[state - idx<'j'>(1)];
			const num_t lap_k =
				A[state + idx<'k'>(1)] - two * center +
				A[state - idx<'k'>(1)];

			// Sum the directional Laplacians first, then scale.
			B[state] = weight * (lap_i + lap_j + lap_k) + center;
		});

		// Second sweep: update A from B
		inner_trav.for_each([=](auto state) {
			using noarr::idx;

			const num_t center = B[state];

			const num_t lap_i =
				B[state + idx<'i'>(1)] - two * center +
				B[state - idx<'i'>(1)];
			const num_t lap_j =
				B[state + idx<'j'>(1)] - two * center +
				B[state - idx<'j'>(1)];
			const num_t lap_k =
				B[state + idx<'k'>(1)] - two * center +
				B[state - idx<'k'>(1)];

			A[state] = weight * (lap_i + lap_j + lap_k) + center;
		});
	};

	if (use_tiling) {
		// -----------------------------------------------------------------
		// Tiled version: block interior in j and i, hoist tile indices.
		//
		// Layout transformation (conceptually):
		//   (i, j, k)  →  (I, i, J, j, k)
		// where:
		//   I, J ... tile indices in i and j
		//   i, j ... intra-tile coordinates
		//
		// We build the proto-structure that:
		//   1) splits j into tiles of size tile_j and hoists J
		//   2) splits i into tiles of size tile_i and hoists I
		//
		// The resulting traversal order is:
		//   for I
		//     for J
		//       for i
		//         for j
		//           for k
		// which keeps k innermost (contiguous), but processes the domain
		// tile-by-tile in i x j.
		// -----------------------------------------------------------------
		auto spatial_tiling =
			interior
			^ noarr::into_blocks<'j', 'J', 'j'>(tile_j) // split j into (J, j)
			^ noarr::hoist<'J'>()                      // move J to the outermost
			^ noarr::into_blocks<'i', 'I', 'i'>(tile_i) // split i into (I, i)
			^ noarr::hoist<'I'>();                     // move I to the outermost

		#pragma scop
		traverser(A, B)
			.order(time_bcast)
			.template for_dims<'t'>([=](auto t_trav) {
				// t_trav has 't' fixed; we only modify spatial dimensions
				auto inner = t_trav.order(spatial_tiling);
				do_time_step(inner);
			});
		#pragma endscop
	} else {
		// -----------------------------------------------------------------
		// Fallback version: original non-tiled traversal.
		// This path is used when (n - 2) is not divisible by the chosen
		// tile sizes, so that we avoid any corner-case handling but still
		// preserve the exact numerical behavior.
		// -----------------------------------------------------------------
		#pragma scop
		traverser(A, B)
			.order(time_bcast)
			.template for_dims<'t'>([=](auto t_trav) {
				// t_trav has 't' fixed; just apply the interior slice
				auto inner = t_trav.order(interior);
				do_time_step(inner);
			});
		#pragma endscop
	}
}

