	using namespace noarr;

	// Stencil coefficients, hoisted out of the inner loops
	constexpr num_t alpha = num_t(0.125);
	constexpr num_t two   = num_t(2.0);

	// Length of the interior in each spatial dimension: indices 1 .. n-2
	const std::size_t interior_len = (n > 2) ? static_cast<std::size_t>(n - 2) : std::size_t(0);

	// Tunable block sizes in i and j
	const std::size_t block_i = tuning.i_block;
	const std::size_t block_j = tuning.j_block;

	// Number of interior points covered by full tiles
	const std::size_t full_i = (block_i > 0) ? (interior_len / block_i) * block_i : 0;
	const std::size_t full_j = (block_j > 0) ? (interior_len / block_j) * block_j : 0;

	const std::size_t tail_i = interior_len - full_i; // remaining rows (in i) after tiling
	const std::size_t tail_j = interior_len - full_j; // remaining columns (in j) after tiling

	// Common interior in k: k in [1, n-2]
	auto k_interior =
		noarr::slice<'k'>(1, interior_len);

	// -----------------------------------------------------------------
	// Spatial regions (all expressed as proto-structures):
	//
	// 1) region_bb : fully tiled rectangle
	//      i in [1, 1+full_i-1], j in [1, 1+full_j-1]
	//    -> tiled with into_blocks in both i and j
	//
	// 2) region_ib : i-tail, j fully tiled
	//      i in [1+full_i, n-2], j in [1, 1+full_j-1]
	//
