	auto region_bb =
		noarr::slice<'i'>(1, full_i) ^
		noarr::slice<'j'>(1, full_j) ^
		k_interior ^
		noarr::into_blocks<'i', 'I', 'i'>(block_i) ^ // I: tile index in i, i: index within tile
		noarr::into_blocks<'j', 'J', 'j'>(block_j) ^ // J: tile index in j, j: index within tile
		noarr::hoist<'I'>() ^                        // iterate tiles in i outermost
		noarr::hoist<'J'>();                         // then tiles in j

