	// The 't' index is ignored when indexing A/B; it is only used to repeat the sweep.
	auto time_bcast = noarr::bcast<'t'>(tsteps);

	#pragma scop
	traverser(A, B)
		.order(time_bcast)
		.template for_dims<'t'>([=](auto t_trav) {
			// -----------------------------------------------------------------
			// Helper: perform one sweep "dst = stencil(src)" on a given
			// traverser view 'trav'.
			//
			// The traverser 'trav' can correspond to any of the four spatial
			// regions (possibly additionally restricted by tiles).
			// -----------------------------------------------------------------
			auto sweep_update = [&](auto &src, auto &dst, auto trav) {
				trav.for_each([&](auto state) {
					using noarr::idx;

					// state contains i,j,k and t (and possibly I,J for tiles);
					// A/B ignore any extra dimensions automatically.
					num_t center = src[state];

					num_t lap_i = src[state + idx<'i'>(1)] - two * center + src[state - idx<'i'>(1)];
					num_t lap_j = src[state + idx<'j'>(1)] - two * center + src[state - idx<'j'>(1)];
					num_t lap_k = src[state + idx<'k'>(1)] - two * center + src[state - idx<'k'>(1)];

					dst[state] = alpha * lap_i
					           + alpha * lap_j
					           + alpha * lap_k
					           + center;
				});
			};

			// -----------------------------------------------------------------
			// First sweep: update B from A
			// -----------------------------------------------------------------
			{
				// Tiled central rectangle (both i and j)
				auto trav_bb = t_trav.order(region_bb);

				// Iterate over tiles explicitly in I (rows of tiles) then J (columns of tiles)
				trav_bb.template for_dims<'I', 'J'>([&](auto block_trav) {
					// Within a tile, for_each iterates i, j, k; k is innermost and
					// contiguous, which is friendly to vectorization.
					sweep_update(A, B, block_trav);
				});

				// Remaining strips and the corner, without explicit tiling
				sweep_update(A, B, t_trav.order(region_ib)); // i-tail, j-block
				sweep_update(A, B, t_trav.order(region_jb)); // j-tail, i-block
				sweep_update(A, B, t_trav.order(region_tt)); // tail-tail
			}

			// -----------------------------------------------------------------
			// Second sweep: update A from B (same spatial partitioning)
			// -----------------------------------------------------------------
			{
				auto trav_bb = t_trav.order(region_bb);
				trav_bb.template for_dims<'I', 'J'>([&](auto block_trav) {
					sweep_update(B, A, block_trav);
				});

				sweep_update(B, A, t_trav.order(region_ib));
				sweep_update(B, A, t_trav.order(region_jb));
				sweep_update(B, A, t_trav.order(region_tt));
			}
		});
