	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(b_layout, k_vec ^ j_vec ^ i_vec);

	// Tuning knobs for kernel behaviour (can be adjusted per target platform)
	// - parallel_dim: which spatial dimension is split across threads (outermost 'i' by default)
	//   In this implementation we always parallelize over the outermost dimension,
	//   so changing layouts while keeping 'i' outermost automatically keeps this effective.
	static constexpr char parallel_dim = 'i';
} tuning;

// -----------------------------------------------------------------------------
// Small helper: apply a point-wise update lambda over the whole spatial domain,
// optionally parallelized across the outermost dimension using OpenMP.
// The traverser 'trav' must describe the full spatial region to process
// (here it will be the interior i,j,k domain for a fixed time step).
// -----------------------------------------------------------------------------
template<class Traverser, class Func>
inline void parallel_for_each_outer(const Traverser &trav, const Func &func) {
	// We use the traverser iterator, which iterates over the outer-most dimension.
	// Each iteration receives a sub-traverser with that outer dimension fixed.
#ifdef _OPENMP
	#pragma omp parallel for schedule(static)
	for (auto sub_trav : trav) {
		// sub_trav has one outer dimension fixed (for this kernel: a single i-slab);
		// we now iterate the remaining (j,k) dimensions serially inside the thread.
		sub_trav.for_each(func);
	}
#else
	// Fallback: single-threaded traversal over full domain.
	trav.for_each(func);
#endif
}

// initialization function
void init_array(int n, auto A, auto B) {
	// A, B: i x j x k, all dimensions of length n
	using namespace noarr;

	traverser(A, B).for_each([=](auto state) {
		auto [i, j, k] = get_indices<'i', 'j', 'k'>(state);

		// Original: A[i][j][k] = B[i][j][k] =
		//   (DATA_TYPE) (i + j + (n - k)) * 10 / n;
		num_t value = num_t((i + j + (n - k)) * 10) / num_t(n);

		A[state] = value;
		B[state] = value;
	});
}

// computation kernel
[[gnu::flatten, gnu::noinline]]
void kernel_heat_3d(int tsteps, int n, auto A, auto B) {
	// A, B: i x j x k
	using namespace noarr;

	// Constants hoisted out of the inner loops for clarity.
	const num_t two   = num_t(2.0);
	const num_t eighth = num_t(0.125);

	// Interior region: i, j, k in [1, n-2]
	// This guarantees that all +/-1 neighbors are inside the valid domain.
	auto interior =
		noarr::slice<'i'>(1, n - 2) ^
		noarr::slice<'j'>(1, n - 2) ^
		noarr::slice<'k'>(1, n - 2);

	// Time "dimension" using broadcast: repeats the same spatial domain tsteps times
	auto time_bcast = noarr::bcast<'t'>(tsteps);

	#pragma scop
	traverser(A, B)
		.order(time_bcast)
		// Iterate over the artificial time dimension 't'.
		.template for_dims<'t'>([&](auto t_trav) {
			// t_trav has 't' fixed; spatial dimensions i, j, k remain.
			// Restrict to the interior region where all neighbors are valid.
			auto inner = t_trav.order(interior);

			// -----------------------------------------------------------------
			// First sweep: update B from A
			// B(i,j,k) <- stencil(A, i,j,k)
			// We parallelize across the outermost spatial dimension (i) by
			// using the traverser iterator inside parallel_for_each_outer.
			// -----------------------------------------------------------------
			parallel_for_each_outer(inner, [=](auto state) {
				using noarr::idx;

				// state contains 'i', 'j', 'k', and 't' (ignored by A/B)
				num_t center = A[state];

				num_t lap_i = A[state + idx<'i'>(1)] - two * center + A[state - idx<'i'>(1)];
				num_t lap_j = A[state + idx<'j'>(1)] - two * center + A[state - idx<'j'>(1)];
				num_t lap_k = A[state + idx<'k'>(1)] - two * center + A[state - idx<'k'>(1)];

				// Combining the three directional Laplacians improves instruction
				// scheduling and keeps the arithmetic explicit.
				B[state] = eighth * (lap_i + lap_j + lap_k) + center;
			});

			// -----------------------------------------------------------------
			// Second sweep: update A from B
			// A(i,j,k) <- stencil(B, i,j,k)
			// This uses the just-updated B from the previous sweep.
			// The two sweeps are separated by the implicit barrier at the end
			// of the OpenMP parallel-for (if enabled), so the update is safe.
			// -----------------------------------------------------------------
