					using noarr::idx;

					const num_t center = B[state];

					const num_t lap_i =
						B[state + idx<'i'>(1)] - two * center + B[state - idx<'i'>(1)];
					const num_t lap_j =
						B[state + idx<'j'>(1)] - two * center + B[state - idx<'j'>(1)];
					const num_t lap_k =
